let suunta = "oikealle"

document.addEventListener('keydown', function(event) {
    if(event.keyCode == 40) {
        suunta = "alas"
    }
    if(event.keyCode == 39) {
        suunta = "oikealle"
    } 
    if(event.keyCode == 37) {
        suunta = "vasemmalle"
    }
    if(event.keyCode == 38) {
        suunta = "ylös"
    }
});


const canvas = document.getElementById("screen");
const ctx = canvas.getContext("2d");

ctx.fillStyle = "black";
ctx.fillRect(0, 0, 500, 500);


async function peli() {

let kakkaX = Math.floor(Math.random() * 20)
let kakkaY = Math.floor(Math.random() * 20)
let matoX = 10
let matoY = 10
let ALKU_NOPEUS = 150
let nopeus = 150 
let pisteet = 0

document.getElementById("pisteet").innerHTML = "" + pisteet

while(matoX < 50) {
 if(matoX == kakkaX && matoY == kakkaY) {
   kakkaX = Math.floor(Math.random() * 20)
   kakkaY = Math.floor(Math.random() * 20)
   pisteet = pisteet + 1
   document.getElementById("pisteet").innerHTML = "" + pisteet
    //nopeus = nopeus - 10 < 0 ? 10 : nopeus - 10
 }
 drawSquare(kakkaX,kakkaY,"green")
 await sleep(nopeus)
 drawSquare(matoX,matoY,"black")
 
 if(suunta==="oikealle") {
  matoX = matoX + 1
 }
 if(suunta==="alas") {
  matoY = matoY + 1
 }
 if(suunta=="vasemmalle") {
  matoX = matoX - 1 
 }
 if(suunta=="ylös") {
 matoY = matoY - 1
 }

if(matoX < 0 || matoX > 19 || matoY < 0 || matoY > 19)
{
window.alert("GAME OVER!!!!!:" + pisteet)
matoX = 10 
matoY = 10
pisteet = 0
suunta = "oikealle"
nopeus = ALKU_NOPEUS
document.getElementById("pisteet").innerHTML = "" + pisteet
}

 drawSquare(matoX,matoY,"red")

}

}

peli()

// sleep time expects milliseconds
function sleep (time) {
  return new Promise((resolve) => setTimeout(resolve, time));
}

function drawSquare(x, y,color) {
ctx.fillStyle = color;
ctx.fillRect(x*25, y*25, 25, 25);
}

